#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=block intra-zone DMZ'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=block intra-zone DMZ'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all '--description=block intra-zone DMZ'
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all '--description=block intra-zone DMZ'
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=203.0.113.0/25 --dest-ip-ranges=10.30.0.10/32,10.30.0.25/32 --layer4-configs=tcp:22 --enable-logging --description=Block_Partner_SSH
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=203.0.113.0/25 --dest-ip-ranges=10.30.0.10/32,10.30.0.25/32 --layer4-configs=tcp:22 --enable-logging --description=Block_Partner_SSH
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging --description=LAN1_to_DMZ_Reject
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging --description=LAN1_to_DMZ_Reject
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   LAN1_Outgoing: the source of the rule is in zone LAN1, and a rule of Google Cloud names no zone: give the networks behind LAN1 with --zone-network; the destination of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network
#   WAN_to_Web: the source of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network; the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   WAN_to_Mail: the source of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network; the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   Admin_Mgmt: the source of the rule is in zone LAN1, and a rule of Google Cloud names no zone: give the networks behind LAN1 with --zone-network; the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   Monitor_Ping: what it allows cannot be said by a rule of Google Cloud
#   Old_Rule: the source of the rule is in zone LAN1, and a rule of Google Cloud names no zone: give the networks behind LAN1 with --zone-network; the destination of the rule is in zone LAB, and a rule of Google Cloud names no zone: give the networks behind LAB with --zone-network
#   Alice_Workhours: schedule 'WORKHOURS' is not converted; the rule would apply at all times; source user match alice is not converted; the source of the rule is in zone LAN1, and a rule of Google Cloud names no zone: give the networks behind LAN1 with --zone-network; the destination of the rule is in zone WAN, and a r
#   DNS_From_Port: the source of the rule is in zone LAN1, and a rule of Google Cloud names no zone: give the networks behind LAN1 with --zone-network; the destination of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network
#   Country_Block: references 'COUNTRY_X': geography XX: not an address FWShift can read; the source 'COUNTRY_X' holds members only its platform knows; a rule of Google Cloud names addresses
#   Portal_Access: the source of the rule is in zone LAN1, and a rule of Google Cloud names no zone: give the networks behind LAN1 with --zone-network; host name object PORTAL: the rules are written with addresses
#   VS_Only: not converted: ctmatch dnat: matches only connections that a virtual server translated; the source of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network; the destination of the rule is in zone DMZ, and a rule of Google Cloud names no z
#   ESP_Out: the source of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network; the destination of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network
#   V6_LAN_Out: the source of the rule is in zone LAN1, and a rule of Google Cloud names no zone: give the networks behind LAN1 with --zone-network; the destination of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network
#   V6_Admin_Web: the source of the rule is in zone LAN1, and a rule of Google Cloud names no zone: give the networks behind LAN1 with --zone-network; the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   V6_Ping: what it allows cannot be said by a rule of Google Cloud

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
